# Chromatic number check
def is_k_colorable(adj, n, k):
    colors = [-1] * n
    def backtrack(v):
        if v == n:
            return True
        for c in range(k):
            if all(colors[u] != c for u in adj[v]):
                colors[v] = c
                if backtrack(v + 1):
                    return True
                colors[v] = -1
        return False
    return backtrack(0)

for k in range(1, 6):
    if is_k_colorable(adj, 9, k):
        print(f"\nChromatic number: {k} (need 2 <= chi <= 4)")
        break

